var PEAR_Utils3 = Class.create();
PEAR_Utils3.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


getApplicativeAccessByBp_v3: function(rowsJson) {

    if (!rowsJson) {
        rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
    }

    // gs.info('getApplicativeAccessByBp rowsJson3 ' + rowsJson);

    var rows = [];
    try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

    // gs.info('getApplicativeAccessByBp rows length ' + rows.length);
	var outMap = {};

	for(z=0;z<rows.length;z++)
	{
		var bpIds = rows[z].business_profile.toString().split(',');
		var prjIds = rows[z].projects.toString().split(',');

		if (!bpIds.length)
			return '[]';

		if (!prjIds.length)
			return '[]';

		// --- 3. Query tabella BusinessPart<->ApplicativeAccess ---
		var parts = new GlideRecord('x_587457_pear_business_part_of_app_access');
		parts.addQuery('business_profile_id', 'IN', bpIds.join(','));
		parts.query();
		gs.info('getApplicativeAccessByBp parts count ' + parts.getRowCount())

		// --- 4. Uso una mappa per evitare duplicati ---


		// --- 5. Ciclo sulle parti ---
		while (parts.next()) {


			// Prendo gli applicative access collegati
			var aa = new GlideRecord('x_587457_pear_applicative_access');
			gs.info('getApplicativeAccessByBp getConcernedApplicativeAccessOfBusinessPart query per parts ' + parts.sys_id + ' è ' + this.getConcernedApplicativeAccessOfBusinessPart(parts.sys_id))

			// Aggiungo la condizione complessa del business part
			aa.addEncodedQuery(this.getConcernedApplicativeAccessOfBusinessPart(parts.sys_id));

			// Filtra i progetti passati in input
			aa.addQuery('project', 'IN', prjIds.join(','));

			aa.query();
			gs.info('getApplicativeAccessByBp aa query per parts ' +parts.sys_id + ' è '  + aa.getEncodedQuery())

			// --- 6. Ciclo sugli applicative access ---
			while (aa.next()) {

				var id = aa.getUniqueValue();

				// Mappa per evitare duplicati
				outMap[id] = {
					business_part: parts.getValue('label'),
					number: aa.getDisplayValue('number'),
					label: aa.getDisplayValue('label'),
					app_id: aa.getDisplayValue('app_id'),
					app_access_format: aa.app_id.applicative_access_format.format.toString(),
					technical_role: aa.getDisplayValue('technical_role'),
					business_unit: aa.getDisplayValue('business_unit'),
					organization: aa.getDisplayValue('organization'),
					project: aa.getDisplayValue('project'),
					group: aa.getDisplayValue('group'),
					company: aa.getDisplayValue('company')
				};
			}
		}
	}
    // --- 7. Converto la mappa in array finale ---
    var out = Object.keys(outMap).map(function(k){ return outMap[k]; });

    gs.info('getApplicativeAccessByBp OUTPUT json ' + new global.JSON().encode(out));

    return new global.JSON().encode(out);
},


getApplicativeAccessByBp_v2: function(rowsJson) {

    // --- 1. Recupero input JSON ---
    if (!rowsJson) {
        rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
    }

    gs.info('getApplicativeAccessByBp rowsJson2 ' + rowsJson);

    var rows = [];
    try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

    // --- 2. Raccolta BP e progetti senza duplicati ---
    var bpSet = {};
    var prjSet = {};

    rows.forEach(function(r){
        if (r.business_profile)
            bpSet[r.business_profile.trim()] = true;

        if (r.projects)
            prjSet[r.projects.trim()] = true;
    });

    var bpIds = Object.keys(bpSet).filter(function(id){ return id; });
    var prjIds = Object.keys(prjSet).filter(function(id){ return id; });

    gs.info('bpIds: ' + bpIds.join(','));
    gs.info('prjIds: ' + prjIds.join(','));

    if (!bpIds.length)
        return '[]';

    if (!prjIds.length)
        return '[]';

    // --- 3. Query tabella BusinessPart<->ApplicativeAccess ---
    var parts = new GlideRecord('x_587457_pear_business_part_of_app_access');
    parts.addQuery('business_profile_id', 'IN', bpIds.join(','));
    parts.query();

    // --- 4. Uso una mappa per evitare duplicati ---
    var outMap = {};

    // --- 5. Ciclo sulle parti ---
    while (parts.next()) {

        gs.info('BP-Part label: ' + parts.label);

        // Prendo gli applicative access collegati
        var aa = new GlideRecord('x_587457_pear_applicative_access');

        // Aggiungo la condizione complessa del business part
        aa.addQuery(this.getConcernedApplicativeAccessOfBusinessPart(parts.sys_id));

        // Filtra i progetti passati in input
        aa.addQuery('project', 'IN', prjIds.join(','));

        aa.query();

        // --- 6. Ciclo sugli applicative access ---
        while (aa.next()) {

            var id = aa.getUniqueValue();

            // Mappa per evitare duplicati
            outMap[id] = {
				business_part: parts.getValue('label'),
                number: aa.getDisplayValue('number'),
                label: aa.getDisplayValue('label'),
                app_id: aa.getDisplayValue('app_id'),
                app_access_format: aa.app_id.applicative_access_format.format.toString(),
                technical_role: aa.getDisplayValue('technical_role'),
                business_unit: aa.getDisplayValue('business_unit'),
                organization: aa.getDisplayValue('organization'),
                project: aa.getDisplayValue('project'),
                group: aa.getDisplayValue('group'),
                company: aa.getDisplayValue('company')
            };
        }
    }

    // --- 7. Converto la mappa in array finale ---
    var out = Object.keys(outMap).map(function(k){ return outMap[k]; });

    gs.info('getApplicativeAccessByBp OUTPUT json ' + new global.JSON().encode(out));

    return new global.JSON().encode(out);
},



	getApplicativeAccessByBp: function(rowsJson) {

	if (!rowsJson) {
    	var rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
	}

	gs.info('getApplicativeAccessByBp rowsJson2 ' + rowsJson);

    var rows = [];
    try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

    var bpSet = {}; 
    var prjSet = {}; 
    rows.forEach(function(r){
      if (r.business_profile) bpSet[r.business_profile] = 1;
      if (r.projects) prjSet[r.projects] = 1;
    });

    var bpIds = Object.keys(bpSet).toString().split(',');
    var prjIds = Object.keys(prjSet).toString().split(',');
	gs.info('prjIds ' + prjIds)
	gs.info('prjIds.toString() ' + prjIds.toString())

    if (!bpIds.length)
      return '[]';
    var parts = new GlideRecord('x_587457_pear_business_part_of_app_access'); // BP↔App
    parts.addQuery('business_profile_id', 'IN', bpIds.join(','));
    parts.query();

	var outMap = {};
    var out = [];
    while (parts.next()) {
		gs.info('getApplicativeAccessByBp parts label ' + parts.label)

      var aa = new GlideRecord('x_587457_pear_applicative_access');
      aa.addQuery(this.getConcernedApplicativeAccessOfBusinessPart(parts.sys_id));
      aa.addQuery('project', 'IN', prjIds.join(','));
      aa.query();
      while (aa.next()) {

		var format = aa.app_id.applicative_access_format.format.toString();
		// out.push({
		outMap[aa.getUniqueValue()] = {
			number: aa.getDisplayValue('number'),
			label: aa.getValue('label'),
			app_id: aa.getDisplayValue('app_id'),
			app_access_format: format,
			technical_role: aa.getDisplayValue('technical_role'),
			business_unit : aa.getDisplayValue('business_unit'),
			organization : aa.getDisplayValue('organization'),
			project : aa.getDisplayValue('project'),
			group : aa.getDisplayValue('group'),
			company : aa.getDisplayValue('company')
        };
      }
    }

	gs.info('getApplicativeAccessByBp PEAR_Preview json ' + new global.JSON().encode(out))
    return new global.JSON().encode(out);
  },



	getProjectsByBusinessProfile: function (BusinessProfileId) {

		gs.info('getProjectsByBusinessProfile START for Business profile ' + BusinessProfileId)

		var BusinessProfileRequiredProjects = [];
		// 1) Business Parts attivi per BP
		var BusinessPart = new GlideRecord('x_587457_pear_business_part_of_app_access');
		BusinessPart.addQuery('business_profile_id', BusinessProfileId);
		// BusinessPart.addQuery('status', 'active');
		BusinessPart.query();
		gs.info('getProjectsByBusinessProfile BusinessPart query ' + BusinessPart.getEncodedQuery());
		var ApplicativeAccessquery = "";
		while(BusinessPart.next())
		{
			if(ApplicativeAccessquery == "")
				ApplicativeAccessquery += this.getConcernedApplicativeAccessOfBusinessPart(BusinessPart.sys_id);
			else
				ApplicativeAccessquery = ApplicativeAccessquery + "^NQ" + this.getConcernedApplicativeAccessOfBusinessPart(BusinessPart.sys_id);
		}
		if(ApplicativeAccessquery == "")
			return ""
		else
		{
			var ApplicativeAccess = new GlideRecord('x_587457_pear_applicative_access');
			ApplicativeAccess.addEncodedQuery(ApplicativeAccessquery);
			ApplicativeAccess.query();
			while(ApplicativeAccess.next())
				if(!BusinessProfileRequiredProjects.toString().contains(ApplicativeAccess.project.toString()))
					BusinessProfileRequiredProjects.push(ApplicativeAccess.project.toString())

			// gs.info('getProjectsByBusinessProfile Final Query ' + ApplicativeAccessquery)
			// gs.info('getProjectsByBusinessProfile BusinessProfileRequiredProjects ' + BusinessProfileRequiredProjects)
			return BusinessProfileRequiredProjects
		}
    },



	getConcernedApplicativeAccessOfBusinessPart: function (bp_sysId) {

		var query = "";
		var aa_array = [];
		var AllLabelComponents = ['technical_role','business_unit','organization','project','group','company'];
		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}

		// gs.info('getConcernedApplicativeAccessOfBusinessPart ' + bp_sysId);

		var bp_LabelCompontents = [];
		var bp = new GlideRecord('x_587457_pear_business_part_of_app_access');
		if(bp.get(bp_sysId) && bp.status == 'enable')
		{
			for (i=0; i<AllLabelComponents.length;i++)
			{
				if(!gs.nil(bp.getValue(AllLabelComponents[i])))
					//bp_LabelCompontents.push(bp.getValue(AllLabelComponents[i]))
					bp_LabelCompontents.push(AllLabelComponents[i])
			}
			// gs.info('getConcernedApplicativeAccessOfBusinessPart bp_LabelCompontents ' + bp_LabelCompontents.toString());

			var aa = new GlideRecord('x_587457_pear_applicative_access');
			for(j=0;j<bp_LabelCompontents.length;j++)
			{
				// gs.info('getConcernedApplicativeAccessOfBusinessPart bp_LabelCompontents[j] ' + bp_LabelCompontents[j] + ' > ' + bp.getValue(bp_LabelCompontents[j]))

				aa.addQuery(bp_LabelCompontents[j],bp.getValue(bp_LabelCompontents[j]))
			}
			aa.query();
			// gs.info('getConcernedApplicativeAccessOfBusinessPart aa query ' + aa.getEncodedQuery())
			query = aa.getEncodedQuery();
			while(aa.next())
			{
				aa_array.push(aa.sys_id.toString())
			}

		}
		if(aa_array.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + aa_array.toString();
		//return query;
	}, 

	getApplicativeAccessFormatbyApp: function (Application){

		var result = "";
		if (!Application) {
			Application = this.getParameter('sysparm_Application');
		}
		gs.info('getApplicativeAccessFormatbyApp Application ' + Application)
		var app = new GlideRecord('x_587457_pear_application');
		if(app.get(Application))
			result = app.applicative_access_format.format + "|" + app.applicative_access_format.separator;

		return result;

	},

    type: 'PEAR_Utils3'
});
